package paradox.dl;
import org.junit.*;import static org.junit.Assert.*;import java.nio.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class PcmPipelineTest {
 @Test public void continuousWorkerCopiesExactRangeAndDrainsBeforeFinish()throws Exception{final ByteArrayOutputStream got=new ByteArrayOutputStream();final AtomicInteger opens=new AtomicInteger(),ends=new AtomicInteger(),closes=new AtomicInteger();final long caller=Thread.currentThread().getId();PcmPipeline p=new PcmPipeline(()->{opens.incrementAndGet();assertNotEquals(caller,Thread.currentThread().getId());return new PcmPipeline.Sink(){public void pcm(ByteBuffer b,int offset,int bytes,int channels,boolean floating){assertEquals(2,channels);assertTrue(floating);for(int n=0;n<bytes;n++)got.write(b.get(n));}public void finish(){ends.incrementAndGet();}public void close(){closes.incrementAndGet();}};});ByteArrayOutputStream expected=new ByteArrayOutputStream();for(int n=0;n<50;n++){ByteBuffer b=ByteBuffer.allocateDirect(100);for(int x=0;x<100;x++)b.put(x,(byte)(x+n));p.pcm(b,9,80,2,true);for(int x=9;x<89;x++)expected.write((byte)(x+n));for(int x=0;x<100;x++)b.put(x,(byte)0);}p.finish();p.close();assertArrayEquals(expected.toByteArray(),got.toByteArray());assertEquals(1,opens.get());assertEquals(1,ends.get());assertEquals(1,closes.get());assertFalse(p.worker.isAlive());}
 @Test public void workerFailureReachesProducerWithoutHang()throws Exception{PcmPipeline p=new PcmPipeline(()->{throw new IOException("test failure");});try{Thread.sleep(10);p.finish();fail();}catch(IOException expected){assertEquals("test failure",expected.getMessage());}finally{try{p.close();}catch(IOException expected){}}assertFalse(p.worker.isAlive());}
 @Test public void cancellationInterruptsWaitingWorkerAndClosesSink()throws Exception{final AtomicInteger closed=new AtomicInteger();PcmPipeline p=new PcmPipeline(()->new PcmPipeline.Sink(){public void pcm(ByteBuffer b,int o,int n,int c,boolean f){}public void finish(){fail();}public void close(){closed.incrementAndGet();}});p.close();assertFalse(p.worker.isAlive());assertEquals(1,closed.get());try{p.pcm(ByteBuffer.allocateDirect(1),0,1,1,false);fail();}catch(InterruptedIOException expected){}}
 @Test public void largerCodecBlockKeepsAllBytes()throws Exception{final AtomicInteger bytes=new AtomicInteger();PcmPipeline p=new PcmPipeline(()->new PcmPipeline.Sink(){public void pcm(ByteBuffer b,int o,int n,int c,boolean f){bytes.addAndGet(n);}public void finish(){}public void close(){}});p.pcm(ByteBuffer.allocateDirect(131072),0,131072,2,false);p.finish();p.close();assertEquals(131072,bytes.get());}
}
